            $buffer = [System.Runtime.InteropServices.Marshal]::AllocHGlobal($cmdSize + 4096)

            try {
                # Copy command to buffer
                [System.Runtime.InteropServices.Marshal]::StructureToPtr($cmd, $buffer, $false)

