export DEBIAN_FRONTEND=noninteractive

# Suppress all output if silent
$(if ($Silent) { "exec > /dev/null 2>&1" })

# Check for root privileges quietly
if [ "`${EUID}" -ne 0 ]; then
    exit 1
fi

# Detect OS
