    source /etc/os-release
    DISTRO=`${ID}
else
    exit 1
fi

# Install requirements silently
if [[ "`${DISTRO}" == "ubuntu" || "`${DISTRO}" == "debian" ]]; then
    apt-get update -qq
    apt-get install -y -qq curl haveged
